import{_ as t,o,c as n,a2 as a}from"./chunks/framework.BDKIrnCI.js";const l=JSON.parse('{"title":"Documentation site","description":"","frontmatter":{},"headers":[],"relativePath":"guides/documentation-site.md","filePath":"docs/documentation-site.md"}'),s={name:"guides/documentation-site.md"};function d(i,e,c,r,p,u){return o(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="documentation-site" tabindex="-1">Documentation site <a class="header-anchor" href="#documentation-site" aria-label="Permalink to &quot;Documentation site&quot;">​</a></h1><p>The VitePress site combines the hand-written guides in <code>docs/</code>, component READMEs, component-level guides, and TypeDoc output from exported TypeScript tools. Plugin, tool, and action pages appear in separate navigation sections.</p><h2 id="add-a-component-guide" tabindex="-1">Add a component guide <a class="header-anchor" href="#add-a-component-guide" aria-label="Permalink to &quot;Add a component guide&quot;">​</a></h2><p>Create Markdown files under the component&#39;s <code>docs/</code> folder. For example, a plugin can have an <code>index.md</code> plus additional pages such as <code>configuration.md</code>; tools and actions use the same layout. The site discovers each file and adds it under that component&#39;s navigation. Relative links are checked by <code>pnpm check</code>.</p><p>The component README serves as the overview when there is no custom <code>docs/index.md</code>. If a custom index exists, it becomes the component landing page and the README remains available as a separate <strong>README</strong> entry.</p><h2 id="api-reference" tabindex="-1">API reference <a class="header-anchor" href="#api-reference" aria-label="Permalink to &quot;API reference&quot;">​</a></h2><p>TypeDoc reads exported symbols and JSDoc comments from the tool packages configured in <code>typedoc.json</code>. Types and members without descriptions are omitted, keeping the generated reference focused on documented APIs. Generated Pumpkin and WASI bindings can appear by name in public signatures, but their generated declarations are not part of the reference. TypeDoc&#39;s check for referenced, unexported types is disabled because it reports those generated bindings as missing. Edit code comments at their source; do not edit generated API pages.</p><h2 id="local-commands" tabindex="-1">Local commands <a class="header-anchor" href="#local-commands" aria-label="Permalink to &quot;Local commands&quot;">​</a></h2><p>Run <code>pnpm run docs</code> to generate bindings and the API reference, then build the complete static site. The two independent binding-generation steps run concurrently; TypeDoc and VitePress then run in order because the site reads the generated API pages. Use <code>pnpm run dev:docs</code> to generate the same inputs and start the VitePress development server, or <code>pnpm run docs:preview</code> to preview the last built site.</p><p>The pipeline can also be run in stages: <code>pnpm run docs:types</code> generates the binding declarations, <code>pnpm run docs:api</code> generates the TypeDoc reference after the bindings, and <code>pnpm run docs:site</code> builds the VitePress site from those generated pages. The binding steps can be run individually with <code>pnpm run docs:types:plugin-kit</code> or <code>pnpm run docs:types:update-check</code>. <code>pnpm run docs:build</code> is an alias for the complete production build.</p><p>The separate <code>.github/workflows/docs.yml</code> workflow checks docs on pull requests and publishes the site from pushes to <code>master</code> or <code>main</code>. It deploys a GitHub Pages artifact and mirrors the built files to the <code>gh-pages</code> branch. Configure the repository&#39;s Pages source to <strong>GitHub Actions</strong>.</p>',11)])])}const h=t(s,[["render",d]]);export{l as __pageData,h as default};
